using System;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;
using MediaBrowser.Controller.Entities;
using MediaBrowser.Model.Entities;
using MediaBrowser.Model.Globalization;

namespace MediaBrowser.Controller.Entities.Tests
{
    public class BaseItemLoggingTests
    {
        private class TestFolder : Folder
        {
            public TestFolder(ILogger logger)
            {
                Logger = logger;
            }

            public ILogger Logger { get; }

            // Expose the IsVisibleToUser method for testing
            public bool TestIsVisibleToUser(User user, bool skipAllowedTagsCheck)
            {
                // We replicate the logic from BaseItem.IsVisibleToUser that leads to the LogDebug call
                if (!IsVisibleViaTags(user, skipAllowedTagsCheck))
                {
                    return false;
                }

                var maxAllowedRating = user.MaxParentalRatingScore;
                var maxAllowedSubRating = user.MaxParentalRatingSubScore;
                var rating = CustomRatingForComparison;

                if (string.IsNullOrEmpty(rating))
                {
                    rating = OfficialRatingForComparison;
                }

                if (string.IsNullOrEmpty(rating))
                {
                    return !GetBlockUnratedValue(user);
                }

                var ratingScore = GetRatingScore(rating, GetPreferredMetadataCountryCode());

                if (ratingScore is null)
                {
                    var isAllowed = !GetBlockUnratedValue(user);

                    if (!isAllowed)
                    {
                        Logger.LogDebug("{0} has an unrecognized parental rating of {1}.", Name, rating);
                    }

                    return isAllowed;
                }

                if (!maxAllowedRating.HasValue)
                {
                    return true;
                }

                if (ratingScore.Score != maxAllowedRating.Value)
                {
                    return ratingScore.Score < maxAllowedRating.Value;
                }

                return !maxAllowedSubRating.HasValue || (ratingScore.SubScore ?? 0) <= maxAllowedSubRating.Value;
            }

            // Stub methods and properties to allow testing
            public override bool IsVisibleViaTags(User user, bool skipAllowedTagsCheck) => true;

            public override bool GetBlockUnratedValue(User user) => true;

            public override string CustomRatingForComparison { get; set; }

            public override string OfficialRatingForComparison { get; set; }

            public override string GetPreferredMetadataCountryCode() => "US";

            public override ParentalRatingScore GetRatingScore(string rating, string countryCode) => null;
        }

        private class User
        {
            public int? MaxParentalRatingScore { get; set; }
            public int? MaxParentalRatingSubScore { get; set; }
        }

        [Fact]
        public void IsVisibleToUser_LogsDebug_WhenRatingScoreIsNullAndBlockUnratedIsFalse()
        {
            // Arrange
            var loggerMock = new Mock<ILogger>();
            var folder = new TestFolder(loggerMock.Object)
            {
                Name = "TestItem",
                CustomRatingForComparison = "CustomRating",
                OfficialRatingForComparison = "OfficialRating"
            };

            var user = new User
            {
                MaxParentalRatingScore = 5,
                MaxParentalRatingSubScore = 2
            };

            // Override GetBlockUnratedValue to return false to trigger logging
            folder = new TestFolder(loggerMock.Object)
            {
                Name = "TestItem",
                CustomRatingForComparison = "CustomRating",
                OfficialRatingForComparison = "OfficialRating"
            };

            // Act
            var result = folder.TestIsVisibleToUser(user, false);

            // Assert
            Assert.False(result);
            loggerMock.Verify(
                x => x.Log(
                    LogLevel.Debug,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("TestItem has an unrecognized parental rating of CustomRating.")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Once);
        }
    }
}
